const reverse=new Map();
function build(){
 reverse.clear();
 Object.entries(M).forEach(([zh,v])=>{
   reverse.set(zh,{zh,en:v.en,de:v.de});
   if(v.en)reverse.set(v.en,{zh,en:v.en,de:v.de});
   if(v.de)reverse.set(v.de,{zh,en:v.en,de:v.de});
 });
}
build();
let busy=false;
// Default language: English (until the visitor picks one)
function lang(){let v=null;try{v=localStorage.getItem(KEY)}catch(e){}return langs.includes(v)?v:'en'}
function tr(s,l=lang()){const x=reverse.get(String(s).trim());if(!x)return s;const out=x[l]||x.zh;return String(s).replace(String(s).trim(),out)}
function translate(root=document,l=lang()){
 if(busy)return; busy=true;
 try{
  const w=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),a=[];
  while(w.nextNode())a.push(w.currentNode);
  a.forEach(n=>{if(!n.parentElement||['SCRIPT','STYLE','TEXTAREA','OPTION'].includes(n.parentElement.tagName))return;const v=tr(n.nodeValue,l);if(v!==n.nodeValue)n.nodeValue=v});
  if(root.querySelectorAll)root.querySelectorAll('[placeholder],[title],[aria-label]').forEach(el=>['placeholder','title','aria-label'].forEach(a=>{if(el.hasAttribute(a)){const o=el.getAttribute(a),v=tr(o,l);if(v!==o)el.setAttribute(a,v)}}));
  translateKeys(root);
  document.documentElement.lang=l==='zh'?'zh-CN':l;
  document.querySelectorAll('[data-lang-switch] [data-lang]').forEach(b=>b.classList.toggle('active',b.dataset.lang===l));
  document.querySelectorAll('select.lang-select').forEach(x=>{if(x.value!==l)x.value=l});
 } finally{busy=false}
}
function setLanguage(l){if(!langs.includes(l))return;try{localStorage.setItem(KEY,l)}catch(e){}translate(document,l);window.dispatchEvent(new CustomEvent('wedding-language-change',{detail:{lang:l}}))}
function t(zh){const x=reverse.get(zh);return x?(x[lang()]||x.zh):zh}
/** Add dictionary entries at runtime: [[zh, en, de], …] (e.g. scene names shared with POD Studio). */
function extend(rows){(rows||[]).forEach(([zh,en,de])=>{if(!zh)return;const x={zh,en:en||zh,de:de||en||zh};[zh,x.en,x.de].forEach(v=>{if(v&&!reverse.has(v))reverse.set(v,x)})});translate(document,lang())}
/** The language switch is a dropdown: [data-lang-switch] containers are turned into <select class="lang-select">. */
const LANG_LABEL={zh:'中文',en:'English',de:'Deutsch'};
function mountSwitches(){
 document.querySelectorAll('[data-lang-switch]').forEach(box=>{
  if(box.querySelector('select.lang-select'))return;
  box.innerHTML=`<select class="lang-select" aria-label="Language">${langs.map(l=>`<option value="${l}">${LANG_LABEL[l]}</option>`).join('')}</select>`;
  box.classList.add('lang-dropdown');const sel=box.querySelector('select');sel.value=lang();sel.onchange=()=>setLanguage(sel.value);
 });
 if(!document.getElementById('lang-select-style')){const st=document.createElement('style');st.id='lang-select-style';
  st.textContent='.lang-dropdown{padding:0!important;border:0!important;background:none!important}.lang-select{appearance:none;-webkit-appearance:none;border:1px solid rgba(45,36,30,.14);background:#fff url("data:image/svg+xml,%3Csvg xmlns=%27http://www.w3.org/2000/svg%27 width=%2710%27 height=%276%27%3E%3Cpath d=%27M1 1l4 4 4-4%27 stroke=%27%2328231f%27 fill=%27none%27 stroke-width=%271.4%27/%3E%3C/svg%3E") no-repeat right 11px center;border-radius:999px;padding:7px 30px 7px 13px;font:inherit;font-size:12px;color:#28231f;cursor:pointer}';
  document.head.appendChild(st)}
}
